import ctypes
import os
import subprocess
import sys

_SO_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_primes.so")
_C_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_primes.c")

_C_CODE = r"""
#include <stdint.h>
#include <stdlib.h>
#include <math.h>

int64_t count_primes_c(int64_t n) {
    if (n <= 2) return 0;
    int64_t N = n - 1;
    if (N == 2) return 1;
    if (N == 3) return 2;

    int64_t r = (int64_t)sqrt((double)N);
    while ((r + 1) * (r + 1) <= N) r++;
    while (r * r > N) r--;

    int64_t *smalls = (int64_t *)malloc((size_t)(r + 1) * sizeof(int64_t));
    int64_t *larges = (int64_t *)malloc((size_t)(r + 1) * sizeof(int64_t));

    for (int64_t i = 1; i <= r; i++) {
        smalls[i] = (i - 1) >> 1;
    }
    for (int64_t i = 1; i <= r; i += 2) {
        larges[i] = (N / i - 1) >> 1;
    }

    for (int64_t p = 3; p <= r; p += 2) {
        if (smalls[p] == smalls[p - 1]) continue;
        int64_t pcnt = smalls[p - 1];
        int64_t p2 = p * p;
        int64_t max_i = r < (N / p2) ? r : (N / p2);

        for (int64_t i = 1; i <= max_i; i += 2) {
            int64_t k = i * p;
            if (k <= r) {
                larges[i] -= larges[k] - pcnt;
            } else {
                larges[i] -= smalls[N / k] - pcnt;
            }
        }

        for (int64_t j = r; j >= p2; j--) {
            smalls[j] -= smalls[j / p] - pcnt;
        }
    }

    int64_t ans = larges[1] + 1;
    free(smalls);
    free(larges);
    return ans;
}
"""

def _load_lib():
    if not os.path.exists(_SO_PATH):
        with open(_C_PATH, "w") as f:
            f.write(_C_CODE)
        env = os.environ.copy()
        env["TMPDIR"] = os.path.dirname(os.path.abspath(__file__))
        cc = "/Applications/Xcode.app/Contents/Developer/Toolchains/XcodeDefault.xctoolchain/usr/bin/clang"
        if not os.path.exists(cc):
            cc = "cc"
        subprocess.run(
            [cc, "-O3", "-march=native", "-shared", "-fPIC", _C_PATH, "-o", _SO_PATH, "-lm"],
            check=True,
            env=env,
        )
    lib = ctypes.CDLL(_SO_PATH)
    fn = lib.count_primes_c
    fn.argtypes = [ctypes.c_int64]
    fn.restype = ctypes.c_int64
    return fn

_count_primes_c = _load_lib()

def count_primes(n: int) -> int:
    return _count_primes_c(n)

if __name__ == "__main__":
    print(_count_primes_c(int(sys.argv[1])))

